export const SPECS: Spec[] = R.map(([no, file, type, restricted, area, phase, cols]) => ({
  no, file: `${file}.xlsx`, type, restricted, area, phase, columns: cols.split(',').map((c) => c.trim()),
}));
export const specByNo = (no: number) => SPECS.find((s) => s.no === no);

// Who may import or export which spec. SUPER_ADMIN always may.
const AREA_ROLES: [RegExp, UserRole[]][] = [
  [/Lending|Commercial/, ['CREDIT_UNDERWRITER']],
  [/Compliance|IT/, ['COMPLIANCE_MLRO']],
  [/Finance|Management/, ['FINANCE_ADMIN']],
  [/HR/, ['HR_MANAGER']],
  [/Operations|Progression|Bank Desk|QA|Customer Success|Advisory/, ['PROGRESSION_MANAGER', 'CREDIT_UNDERWRITER']],
  [/Sales|Growth|Partnerships/, ['SALES_ADVISOR']],
];
export function rolesFor(spec: Spec): UserRole[] {
  const out = new Set<UserRole>(['SUPER_ADMIN']);
  for (const [re, roles] of AREA_ROLES) if (re.test(spec.area)) roles.forEach((r) => out.add(r));
  // restricted files stay with the owning function only (no advisors)
  if (spec.restricted) out.delete('SALES_ADVISOR');
  return [...out];
}
